1	export type Cell = [number, number];
2	
3	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighbors = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	const survivesToNextGeneration = (
17	  liveNeighbors: number,
18	  isCurrentlyAlive: boolean,
19	): boolean =>
20	  liveNeighbors === 3 || (liveNeighbors === 2 && isCurrentlyAlive);
21	
22	export function nextGeneration(cells: Cell[]): Cell[] {
23	  const livingKeys = new Set(cells.map(cellKey));
24	
25	  // Every live cell casts one vote for each of its 8 neighbors, so this tally
26	  // holds both the candidate cells and their live-neighbor counts in one pass.
27	  const tally = new Map<string, { cell: Cell; liveNeighbors: number }>();
28	  for (const cell of cells) {
29	    for (const neighbor of neighbors(cell)) {
30	      const key = cellKey(neighbor);
31	      const entry = tally.get(key) ?? { cell: neighbor, liveNeighbors: 0 };
32	      entry.liveNeighbors += 1;
33	      tally.set(key, entry);
34	    }
35	  }
36	
37	  const nextCells: Cell[] = [];
38	  for (const [key, { cell, liveNeighbors }] of tally) {
39	    if (survivesToNextGeneration(liveNeighbors, livingKeys.has(key))) {
40	      nextCells.push(cell);
41	    }
42	  }
43	
44	  return nextCells;
45	}
